CREATE TRIGGER UNDGCountryReference_Version_Create
	ON UNDGCountryReference
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT DCR_PK, 'DCR'
	FROM inserted
GO
CREATE TRIGGER UNDGCountryReference_Version_Update
	ON UNDGCountryReference
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON DCR_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
